from-notes-to-maps.code:
EDGES = [
    ("User action", "React form state", "submit"),
    ("React form state", "API route", "POST /tasks"),
    ("API route", "Validation layer", "validates"),
    ("Validation layer", "Postgres row", "persists"),
    ("Postgres row", "Email job", "enqueues"),
]
ASYNC_NODES = {"Email job"}


def trace(start):
    nxt = {a: b for a, b, _ in EDGES}
    path = [start]
    while path[-1] in nxt:
        path.append(nxt[path[-1]])
    return path


def answer_reviewer(path):
    pos = {n: i for i, n in enumerate(path)}
    print("path: " + " -> ".join(path))
    print(f"validation_before_persistence: {pos['Validation layer'] < pos['Postgres row']}")
    print(f"hops_from_action_to_persist: {pos['Postgres row'] - pos['User action']}")
    async_hits = [n for n in path if n in ASYNC_NODES]
    print(f"async_handoffs: {len(async_hits)}")
    print(f"owns_email_send: {async_hits[0] if async_hits else 'request thread'}")


answer_reviewer(trace("User action"))

capstone-failure-autopsy.code:
NOW = 552
FRESH_LIMIT_MIN = 30
STREAMS = {
    "signups":     {"newest_t": 550},
    "activations": {"newest_t": 254},
}
WORKER = {"consumer_lag_events": 312_000, "last_batch_t": 251, "events_queued": True}


def autopsy():
    fresh = {}
    for name in ("signups", "activations"):
        s = STREAMS[name]
        age = NOW - s["newest_t"]
        ok = age <= FRESH_LIMIT_MIN
        fresh[name] = ok
        print(f"stream={name} newest_t={s['newest_t']} age={age}m verdict={'FRESH' if ok else 'STALE'}")
    if fresh["signups"] and fresh["activations"]:
        implicated = "metric-dashboard"
    elif fresh["signups"]:
        implicated = "activation-worker"
    else:
        implicated = "signup-pipeline"
    print(f"implicated: {implicated}")
    confirmed = (WORKER["consumer_lag_events"] > 1000
                 and WORKER["last_batch_t"] <= STREAMS["activations"]["newest_t"])
    print(f"worker_confirmation: {'CONFIRMED' if confirmed else 'UNCONFIRMED'} lag={WORKER['consumer_lag_events']} last_batch_t={WORKER['last_batch_t']}")
    radius = "stale-recoverable" if WORKER["events_queued"] else "data-lost"
    print(f"blast_radius: {radius}")
    print(f"recovery: {'replay-from-offset' if radius == 'stale-recoverable' else 'backfill-required'}")
    print("rejected: restart-email-service restart-dashboard")


autopsy()

final-review-board.code:
NARRATION = ["symptom", "path", "first-wrong", "boundary", "component-blame"]
OBJECTIONS = [
    {"id": 1, "response_s": 20, "outcome": "conceded-repaired", "repair_named": True},
    {"id": 2, "response_s": 75, "outcome": "conceded-repaired", "repair_named": True},
]
TRANSFER = {"repriced_blast_radius": True, "changed_proof_method": True, "label_overlap_pct": 22}
RESPONSE_BOX_S = 90


def narration_kind(events):
    def at(name):
        return events.index(name) if name in events else -1

    sym, first, blame = at("symptom"), at("first-wrong"), at("component-blame")
    causal = sym >= 0 and first >= 0 and sym < first
    if causal and blame >= 0:
        causal = first < blame
    return "CAUSAL" if causal else "BOX-LIST"


def objection_fault(o):
    if o["outcome"] != "conceded-repaired":
        return f"outcome {o['outcome']} — did not concede and repair"
    if not o["repair_named"]:
        return "conceded without naming the repair"
    if o["response_s"] > RESPONSE_BOX_S:
        return f"answered in {o['response_s']}s — outside the {RESPONSE_BOX_S}s box"
    return None


def board(objections):
    narration = narration_kind(NARRATION)
    print(f"narration: {narration}")
    scored = 0
    first_fault = None
    for o in objections:
        fault = objection_fault(o)
        if fault is None:
            scored += 1
        elif first_fault is None:
            first_fault = (o["id"], fault)
        mark = "SCORED" if fault is None else "FAILED"
        print(
            f"objection {o['id']}: outcome={o['outcome']} "
            f"response={o['response_s']}s repair={o['repair_named']} -> {mark}"
        )
    print(f"objections_scored: {scored}/{len(objections)}")
    repriced = (
        TRANSFER["repriced_blast_radius"]
        and TRANSFER["changed_proof_method"]
        and TRANSFER["label_overlap_pct"] <= 30
    )
    print(f"transfer: {'REPRICED' if repriced else 'RELABELED'}")
    passed = narration == "CAUSAL" and scored == len(objections) and repriced
    print(f"gate: {'PASSED' if passed else 'FAILED'}")
    if passed:
        reason = "map improved under attack"
    elif narration != "CAUSAL":
        reason = "narration listed boxes before naming where the system first goes wrong"
    elif first_fault is not None:
        reason = f"objection {first_fault[0]}: {first_fault[1]}"
    else:
        reason = "transfer relabeled the old map instead of repricing the blast radius"
    print(f"reason: {reason}")


board(OBJECTIONS)

REJECTED = OBJECTIONS + [
    {"id": 3, "response_s": 30, "outcome": "argued-flat", "repair_named": False},
    {"id": 4, "response_s": 95, "outcome": "conceded-repaired", "repair_named": True},
]
print("-- rerun with the two objections you authored --")
board(REJECTED)
